(function(){'use strict';var moduleLessons={module1:[{short:"Why Anatomy",full:"Why Anatomy?"},{short:"Locations",full:"Locations of Structures on the Body"},{short:"Pose",full:"Pose with Movements"},{short:"Positions",full:"Positions and Curvatures of the Spine and Pelvis"},{short:"Bone Tissue",full:"Structure of Bone Tissue"},{short:"Skeleton",full:"The Axial and Appendicular Skeletons"},{short:"Joints",full:"Joints in the Skeletal System"},{short:"Variable",full:"Variable Anatomy"},{short:"Tissue Types",full:"Types of Tissue"},{short:"Stretching",full:"Physiology of Stretching"},{short:"Anatomy",full:"Anatomy of the Pelvis, Shoulder Girdle and Trunk"},{short:"Tadasana",full:"Tadasana Alignment"},{short:"Energy",full:"Muscular and Organic Energy"},{short:"Principles",full:"Principles of Forward Folding, Back-Bending, Lateral Bending and Twisting"}],module2:[{short:"History",full:"History of Yoga"},{short:"Breath",full:"Anatomy of the Breath"},{short:"Breathing Dynamics",full:"Breathing Dynamics"},{short:"Movement",full:"Movement of the body with Breath"}]};var headerDefaults={logoImage:'/courses/548/files/20032/preview',logoImageAlt:'White SOM logo circular'};var imageBaseLocal='';var moduleHeaders={'0-1':{bgImage:'/courses/548/files/20074/preview',bgImageAlt:'module-0-bg-2.jpg',title:'Course Orientation',subtitle:'Course Essentials',animVariant:'fade'},'0-2':{bgImage:'/courses/548/files/20075/preview',bgImageAlt:'module-0-bg-1.jpg',title:'Course Orientation',subtitle:'Asana Library',animVariant:'fade'},'0-3':{bgImage:'/courses/548/files/20075/preview',bgImageAlt:'module-0-bg-1.jpg',title:'Course Orientation',subtitle:'Additional Resources',animVariant:'fade'},'0-4':{bgImage:'/courses/548/files/20104/preview',bgImageAlt:'module-0-bg-4.jpg',title:'Course Orientation',subtitle:'Intro to Yoga',animVariant:'fade'},'1':{bgImage:'/courses/548/files/20031/preview',bgImageAlt:'module-1-cutout.png',title:'Module 1',subtitle:'Anatomy, Alignment & Intention',animVariant:'from-left'},'2':{bgImage:'/courses/548/files/20048/preview',bgImageAlt:'module-2-cutout.png',title:'Module 2',subtitle:'Language of Movement & Power of Sequencing',animVariant:'from-right'},'3':{bgImage:'/courses/548/files/20049/preview',bgImageAlt:'module-3-cutout.png',title:'Module 3',subtitle:'Assists, Meditation & Teaching Skills',animVariant:'fade'},'4':{bgImage:'/courses/548/files/20051/preview',bgImageAlt:'module-4-cutout.png',title:'Module 4',subtitle:'From Teaching Skills to Transformation',animVariant:'zoom'}};var currentState={step:1,substep:1,moduleId:null,lessons:null};function createSubstepDots(count,activeSubstep,isActiveStep,isCompleted){if(count<=1)return '';var dots=[];for(var i=1;i<=count;i++){var dotClass='ylms-pb_substep';if(isCompleted){dotClass+=' ylms-pb_substep-completed';}else if(isActiveStep&&i<=activeSubstep){dotClass+=' ylms-pb_substep-completed';}dots.push('<span class="'+dotClass+'"></span>');}return '<div class="ylms-pb_substeps">'+dots.join('')+'</div>';}function createProgressBar(container,lessons,currentStep,currentSubstep){var totalSteps=lessons.length;var shouldAnimate=currentSubstep<=1;var previousProgress,segmentWidth;if(shouldAnimate){previousProgress=currentStep>1?((currentStep-2)/(totalSteps-1))* 100:0;segmentWidth=currentStep>1?(1 /(totalSteps-1))* 100:0;}else{previousProgress=((currentStep-1)/(totalSteps-1))* 100;segmentWidth=0;}var stepsHtml=lessons.map(function(lesson,i){var stepNum=i+1;var isCompleted=stepNum<currentStep;var isActive=stepNum===currentStep;var isLastCompleted=stepNum===currentStep-1;var circleClass='ylms-pb_circle';if(isCompleted)circleClass+=' ylms-pb_completed';else if(isActive)circleClass+=' ylms-pb_active';var labelClass='ylms-pb_label';if(stepNum<=currentStep)labelClass+=' ylms-pb_active';var circleContent;if(isCompleted){var tickClass=(isLastCompleted&&shouldAnimate)?'ylms-pb_tick ylms-pb_tick-animate':'ylms-pb_tick';circleContent='<span class="'+tickClass+'">✓</span>';}else{circleContent=stepNum;}var substepDots=createSubstepDots(lesson.substeps||1,isActive?currentSubstep:1,isActive,isCompleted);return '<div class="ylms-pb_step" data-step="'+stepNum+'">'+'<div class="'+circleClass+'" title="'+lesson.full+'">'+circleContent+'</div>'+'<span class="'+labelClass+'">'+lesson.short+'</span>'+substepDots+'</div>';}).join('');var rightClass=currentStep>totalSteps?'ylms-pb_right ylms-pb_complete':'ylms-pb_right';var containerMaxWidth=totalSteps<=6?totalSteps * 72:Math.min(1400,totalSteps * 100);var containerPad=totalSteps<=6?24:32;container.innerHTML='<div class="ylms-pb_wrapper" data-steps="'+totalSteps+'">'+'<div class="ylms-pb_steps-container" style="--ylms-pb-previous: '+previousProgress+'; --ylms-pb-current: '+(previousProgress+segmentWidth)+'; --ylms-pb-pad: '+containerPad+'px; max-width: '+containerMaxWidth+'px">'+'<div class="ylms-pb_track"></div>'+'<div class="ylms-pb_left"></div>'+'<div class="ylms-pb_fill-static"></div>'+(shouldAnimate?'<div class="ylms-pb_fill-animated"></div>':'')+'<div class="'+rightClass+'"></div>'+'<div class="ylms-pb_steps">'+stepsHtml+'</div>'+'</div>'+'</div>';}function updateSubsteps(substep){currentState.substep=substep;var container=document.getElementById('ylms-'+currentState.moduleId+'-progress');if(container){var activeStep=container.querySelector('.ylms-pb_step[data-step="'+currentState.step+'"]');if(activeStep){var dots=activeStep.querySelectorAll('.ylms-pb_substep');dots.forEach(function(dot,i){dot.classList.remove('ylms-pb_substep-completed','ylms-pb_substep-active');if(i+1<=substep){dot.classList.add('ylms-pb_substep-completed');}});}}}function createTabsFromPanels(container){var panels=document.querySelectorAll('[data-panel]');if(panels.length===0)return;var tabData=[];panels.forEach(function(panel,index){var panelId=panel.dataset.panel||(index+1);var heading=panel.querySelector('h1, h2, h3, h4');var label=heading?heading.textContent.trim():'Tab '+(index+1);tabData.push({id:panelId,label:label});panel.classList.add('ylms-tb_panel');if(index===0)panel.classList.add('ylms-tb_active');});if(tabData.length<=1)return;var tabsHtml=tabData.map(function(tab,index){var activeClass=index===0?' ylms-tb_active':'';return '<button class="ylms-tb_tab'+activeClass+'" data-tab="'+tab.id+'">'+tab.label+'</button>';}).join('');var tabContainer=document.createElement('div');tabContainer.className='ylms-tb_container';tabContainer.innerHTML='<div class="ylms-tb_tabs">'+tabsHtml+'</div>';var panelsContainer=document.createElement('div');panelsContainer.className='ylms-tb_panels';panels.forEach(function(panel){panelsContainer.appendChild(panel);});container.after(tabContainer);tabContainer.after(panelsContainer);var tabs=tabContainer.querySelectorAll('.ylms-tb_tab');tabs.forEach(function(tab){tab.addEventListener('click',function(){var tabId=this.dataset.tab;var tabIndex=Array.from(tabs).indexOf(this)+1;tabs.forEach(function(t){t.classList.remove('ylms-tb_active');});this.classList.add('ylms-tb_active');panels.forEach(function(p){p.classList.remove('ylms-tb_active');});var targetPanel=document.querySelector('[data-panel="'+tabId+'"]');if(targetPanel)targetPanel.classList.add('ylms-tb_active');updateSubsteps(tabIndex);});});var currentLesson=currentState.lessons[currentState.step-1];if(currentLesson)currentLesson.substeps=tabData.length;createProgressBar(container,currentState.lessons,currentState.step,currentState.substep);}function calculateReadTime(){var WORDS_PER_MIN=200;var SECS_PER_IMAGE=10;var MINS_PER_IFRAME=5;var contentEl=document.querySelector('.user_content');if(!contentEl)return 0;var textContent=contentEl.textContent||'';var words=textContent.trim().split(/\s+/).filter(function(w){return w.length>0;}).length;var readMins=words / WORDS_PER_MIN;var imageCount=contentEl.querySelectorAll('img').length;var imageMins=(imageCount * SECS_PER_IMAGE)/ 60;var videoMins=0;contentEl.querySelectorAll('[data-duration]').forEach(function(el){videoMins+=(parseInt(el.dataset.duration,10)||0)/ 60;});var timecodeMins=0;document.querySelectorAll('.ylms-time-code').forEach(function(el){var text=el.textContent.trim();var match=text.match(/(\d+)\.(\d+)/);if(match){timecodeMins+=(parseInt(match[1],10)||0)+((parseInt(match[2],10)||0)/ 60);}});var iframeCount=contentEl.querySelectorAll('iframe').length;var iframeMins=iframeCount * MINS_PER_IFRAME;var totalMins=Math.ceil(readMins+imageMins+videoMins+timecodeMins+iframeMins);if(totalMins<1)totalMins=1;return totalMins;}function renderReadTime(container){var mins=calculateReadTime();var badge=document.createElement('div');badge.className='ylms-pb_readtime';badge.textContent=mins+' min';container.after(badge);}function parseProgress(value){if(!value)return{step:1,substepCount:1,substep:1};var parts=value.split('-').map(function(p){return parseInt(p,10);});return{step:parts[0]||1,substepCount:parts[1]||1,substep:parts[2]||1};}function renderModuleHeader(container,moduleNum){var header=moduleHeaders[moduleNum];if(!header)return false;var d=headerDefaults;var variantClass='ylms-img-blended ylms-img-blended--'+(header.animVariant||'from-left');container.innerHTML='<img class="'+variantClass+'" src="'+header.bgImage+'" alt="'+header.bgImageAlt+'" />'+'<div class="ylms-header_container">'+'<img class="ylms-header_logo" src="'+(header.logoImage||d.logoImage)+'" alt="'+(header.logoImageAlt||d.logoImageAlt)+'" />'+'<div>'+'<h1>'+header.title+'</h1>'+'<h2>'+header.subtitle+'</h2>'+'</div>'+'</div>';return true;}function init(){var headerContainer=document.getElementById('ylms-header');if(headerContainer&&headerContainer.dataset.module){renderModuleHeader(headerContainer,headerContainer.dataset.module);}var readTimeOnly=document.getElementById('ylms-reading-time');if(readTimeOnly){renderReadTime(readTimeOnly);return;}var container=null;var moduleId=null;var lessons=null;for(var key in moduleLessons){var containerId='ylms-'+key+'-progress';var el=document.getElementById(containerId);if(el){container=el;moduleId=key;lessons=moduleLessons[key];break;}}if(!container){console.log('[YLMS-PB] No progress bar container found');return;}currentState.moduleId=moduleId;currentState.lessons=lessons;var progress=parseProgress(container.dataset.progress);currentState.step=progress.step;currentState.substep=progress.substep;var currentLesson=lessons[currentState.step-1];if(currentLesson&&progress.substepCount>1){currentLesson.substeps=progress.substepCount;}createTabsFromPanels(container);if(!document.querySelector('.ylms-tb_container')){createProgressBar(container,lessons,currentState.step,currentState.substep);}window.ylmsUpdateSubstep=updateSubsteps;renderReadTime(container);}function initAttachments(){var contentEl=document.querySelector('.user_content');if(!contentEl)return;var links=contentEl.querySelectorAll('a[href*="/files/"]');if(links.length===0)return;var seen={};var items=[];var stripWords=/\b(download|view|click|open|here|file|preview|the|this|a|an)\b/gi;links.forEach(function(link){var href=link.href;var match=href.match(/\/files\/(\d+)/);var fileId=match?match[1]:href;if(seen[fileId])return;seen[fileId]=true;var text=link.textContent.trim().replace(stripWords,'').replace(/\s{2,}/g,' ').trim();items.push({href:href,text:text||'File'});});if(items.length===0)return;var headerEl=document.getElementById('ylms-header');if(!headerEl)return;var dlIcon='<svg class="ylms-att_icon" viewBox="0 0 1920 1920" xmlns="http://www.w3.org/2000/svg"><path d="m1807.093 1482.477 79.736 79.963-355.313 355.312H355.346L.035 1562.44l79.85-79.963 322.22 322.334H1484.76l322.334-322.334ZM997.677-.033v1167.02l355.313-355.313 79.962 79.85-491.858 491.633L449.46 891.524l79.962-79.85 355.313 355.313V-.033h112.941Z" fill-rule="evenodd"/></svg>';var listHtml=items.map(function(item){return '<a class="ylms-att_link" href="'+item.href+'" target="_blank">'+dlIcon+item.text+'</a>';}).join('');var widget=document.createElement('div');widget.className='ylms-att_widget';widget.innerHTML='<button class="ylms-att_btn" aria-label="Downloads">'+dlIcon+'<span class="ylms-att_badge">'+items.length+'</span>'+'</button>'+'<div class="ylms-att_dropdown">'+'<div class="ylms-att_dropdown-header">Downloads</div>'+listHtml+'</div>';headerEl.appendChild(widget);var btn=widget.querySelector('.ylms-att_btn');btn.addEventListener('click',function(e){e.stopPropagation();widget.classList.toggle('ylms-att_open');});document.addEventListener('click',function(e){if(!widget.contains(e.target)){widget.classList.remove('ylms-att_open');}});}setTimeout(init,250);setTimeout(initAttachments,500);})();